CREATE TABLE IF NOT EXISTS governed_bail_cases(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,defendant_id TEXT NOT NULL,prepared_by TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','pending_review','human_decided','disputed','closed')),case_file JSONB NOT NULL,case_digest CHAR(64) NOT NULL,human_decision JSONB,decided_by TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS governed_bail_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES governed_bail_cases(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS governed_bail_disputes(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES governed_bail_cases(id),submitted_by TEXT NOT NULL,reason TEXT NOT NULL,evidence_refs JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL CHECK(status IN('open','investigating','resolved','withdrawn')),resolution TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS governed_bail_events_lookup ON governed_bail_events(tenant_id,case_id,occurred_at);
CREATE OR REPLACE FUNCTION reject_governed_bail_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'governed bail events are append-only'; END $$;
DROP TRIGGER IF EXISTS governed_bail_events_append_only ON governed_bail_events;
CREATE TRIGGER governed_bail_events_append_only BEFORE UPDATE OR DELETE ON governed_bail_events FOR EACH ROW EXECUTE FUNCTION reject_governed_bail_event_mutation();
